function icExtraerTipo(texto) {
  const t = String(texto || '').toLowerCase();
  if (/\b(depto|departamento)\b/i.test(t)) return 'depto';
  if (/\bcasa\b/i.test(t)) return 'casa';
  if (/\blote\b/i.test(t)) return 'lote';
