          derivacion.categoria === 'C'
            ? 'DERIVACION C'
            : derivacion.categoria === 'B'
              ? 'AVISO B'
              : 'LEAD',
        nombre: leadData.nombre || nombreUsuario,
        canal: 'telegram',
        chatId: chatId,
        leadId: 'telegram:' + String(chatId || ''),
        zona: leadData.zona || promptData.zona_detectada || '',
        presupuesto: leadData.presupuesto || promptData.presupuesto_detectado || '',
        operacion: leadData.operacion || promptData.operacion_detectada || '',
        urgencia: leadData.urgencia || '',
        resumen: leadData.resumen || textoUsuario,
        ultimoMensaje: textoUsuario,
        motivo: derivacion.motivo || '',
        panelBase: botConfigParse.panel_base_url,
      })
    : String(scoreTemp.notif_resumen || '');
if (promptData.sheets_error && promptData.alertar_sheets) {
  avisoVendedorTexto =
    String(promptData.sheets_alerta_texto || '').trim() ||
    'Sheets caído: ' +
      String(promptData.sheets_error_nodo || 'Leer Stock') +
      ' ' +
      String(promptData.sheets_error_msg || '').slice(0, 160);
}
if (promptData.sheets_recuperacion) {
  avisoVendedorTexto =
    String(promptData.sheets_recuperacion) +
    (avisoVendedorTexto ? '\n' + avisoVendedorTexto : '');
  derivacion.alertar = true;
}

if (derivacion.alertar && avisoVendedorTexto) {
  scoreTemp.notif_resumen = avisoVendedorTexto;
}

// Regla de oro (Parche 2): no narrar "ya le aviso al asesor" — la entrega al
// vendedor es async y puede fallar. Reescribir a confirmacion sin promesa.
respuestaBot = String(respuestaBot || '')
  .replace(
    /\b(ya\s+le\s+aviso|ya\s+avis[eé]|le\s+aviso\s+al\s+asesor|aviso\s+al\s+asesor)\b[^.!?]*/gi,
    'El asesor te confirma por aca',
  )
  .replace(/\s{2,}/g, ' ')
  .trim();

// Ban cierre pasivo
if (
  /\bcualquier cosa avisame\b/i.test(String(respuestaBot || '')) ||
  (typeof suenaPlantillaRobot === 'function' &&
    suenaPlantillaRobot(respuestaBot) &&
    !propiedadesMostrar.length &&
    !forzarHandoffVisita)
) {
  if (forzarHandoffVisita) {
    // keep
  } else if (propiedadesMostrar.length) {
    respuestaBot = armarIntroPropiedades(presupuestoDetectado, idxVariante, esCurioso);
  } else {
    respuestaBot =
      'Decime si queres mas detalle de alguna o coordinamos visita.';
  }
}

// Rate limit: silencio + reintento Groq completo (cola justa). Sin "dame un segundo".
let reenvioRateLimit = false;
let reenvioTipo = '';
let reenvioIds = [];
let reenvioLink = '';
let retryGroq = false;
let waitRetrySec = 0;
let notifyOwnerGroq = false;
const MAX_GROQ_RETRIES = 4;
const MAX_GROQ_WAIT_MS = 5 * 60 * 1000;

if (isRateLimit) {
  try {
    const sdRl = $getWorkflowStaticData('global');
    if (!sdRl.groqTokenCtrl) sdRl.groqTokenCtrl = {};
    const ctrl = sdRl.groqTokenCtrl;
    const bumpMs = Math.max(retryAfterSec, 20) * 1000;
    ctrl.nextSlotAt = Math.max(Number(ctrl.nextSlotAt) || 0, Date.now() + bumpMs);

    if (!sdRl.groqRetry) sdRl.groqRetry = {};
    const st = sdRl.groqRetry[chatId] || { attempts: 0, since: Date.now() };
    if (!st.since) st.since = Date.now();
    st.attempts = Number(st.attempts || 0) + 1;
    sdRl.groqRetry[chatId] = st;

    const elapsed = Date.now() - Number(st.since);
    // Entrega real = fichas o link. Texto stub de 429 NO cuenta.
    const tieneEntrega =
      Boolean(propiedadesMostrar.length) || Boolean(String(citaLinkParse || '').trim());

    if (tieneEntrega) {
      // Ya hay fichas/link → no reintentar Groq; limpiar contador
      delete sdRl.groqRetry[chatId];
      if (propiedadesMostrar.length || sugerenciasIds.length) {
        reenvioRateLimit = false;
        reenvioTipo = 'fichas';
        reenvioIds = (propiedadesMostrar.length
          ? propiedadesMostrar
          : sugerenciasIds
        ).slice(0, 3);
      } else if (citaLinkParse) {
        reenvioTipo = 'link';
        reenvioLink = citaLinkParse;
      }
    } else if (st.attempts <= MAX_GROQ_RETRIES && elapsed < MAX_GROQ_WAIT_MS) {
      // Silencio al cliente; esperar TPM y rellamar Groq con el mismo prompt
      skipReply = true;
      retryGroq = true;
      waitRetrySec = Math.max(retryAfterSec, 20);
      respuestaBot = '';
      mensajeCierre = '';
      mensajesExtra = [];
      propiedadesMostrar = [];
    } else {
      // Agotado: avisar dueño YA y recién ahí un fallback mínimo al cliente
      delete sdRl.groqRetry[chatId];
      notifyOwnerGroq = true;
      skipReply = false;
      retryGroq = false;
      respuestaBot = FALLBACK_GROQ;
      mensajeCierre = '';
      mensajesExtra = [];
    }
  } catch (eRl) {
    notifyOwnerGroq = true;
    skipReply = false;
    respuestaBot = FALLBACK_GROQ;
  }
} else {
  try {
    const sdOk = $getWorkflowStaticData('global');
    if (sdOk.groqRetry && sdOk.groqRetry[chatId]) delete sdOk.groqRetry[chatId];
  } catch (eOk) {}
}

if (!skipReply && !esOffTopic) {
  if (temperatura === 'caliente' && !propiedadesMostrar.length && !forzarStockClasificador && !forzarHandoffVisita) {
    respuestaBot =
      typeof LT_CIERRE_CALIENTE === 'string'
        ? LT_CIERRE_CALIENTE
        : 'Dale, con esto ya puedo avanzar. Te armo visita o preferis que te llame?';
    mensajeCierre = '';
    mensajesExtra = [];
  } else if (temperatura === 'tibio' && !esSaludoTurno) {
    if (!propiedadesMostrar.length && sugerenciasIds.length && forzarStockClasificador) {
      propiedadesMostrar = sugerenciasIds.slice(0, 2);
      respuestaBot = armarIntroPropiedades(presupuestoDetectado, idxVariante, false);
    }
    if (propiedadesMostrar.length) {
      mensajeCierre = pickCierreProps(idxVariante + 1);
    }
  }
}

const tsHist = new Date().toISOString();
const lastHist = historialJson.length
  ? historialJson[historialJson.length - 1]
  : null;
const lastRole = String((lastHist && lastHist.role) || '').toLowerCase();
const lastContent = String(
  (lastHist && (lastHist.content || lastHist.texto)) || '',
).trim();
const userYaEnHistorial =
  (lastRole === 'user' || lastRole === 'cliente') &&
  lastContent === String(textoUsuario || '').trim();
if (!userYaEnHistorial) {
  historialJson.push(
    enriquecerEntradaHistorial(
      { role: 'user', content: textoUsuario, ts: tsHist },
      { intent_detected: leadData.operacion || '' },
    ),
  );
}
if (!skipReply && respuestaBot) {
  const analisisPost = analizarHistorial(historialJson.slice(0, -1), {
    operacion: leadData.operacion || '',
    zona: leadData.zona || visitaData.zona || zonaDetectada,
    presupuesto: presupuestoOut,
  });
  const metaTurno = metaTurnoAprendizaje({
    intencion: leadData.operacion || '',
    operacion: leadData.operacion || '',
    zona: leadData.zona || '',
    presupuesto: presupuestoOut,
    objeciones: analisisPost.objeciones,
    lead_completo: leadCompleto,
    temperatura,
  });
  let textoAsistente = respuestaBot;
  if (mensajeCierre) textoAsistente = textoAsistente + '\n\n' + mensajeCierre;
  historialJson.push(
    enriquecerEntradaHistorial(
      { role: 'assistant', content: textoAsistente, ts: tsHist },
      metaTurno,
    ),
  );
}
const histStoreMax =
  typeof IC_HISTORIAL_STORE_MAX === 'number' ? IC_HISTORIAL_STORE_MAX : 48;
if (historialJson.length > histStoreMax) {
  historialJson = historialJson.slice(historialJson.length - histStoreMax);
}

const sd = $getWorkflowStaticData('global');
if (!sd.historialByChat) sd.historialByChat = {};
sd.historialByChat[chatId] = historialJson;

const ahora = new Date().toISOString();

respuestaBot = humanizarVoz(sanitizarPuntuacion(respuestaBot));
// Anti "Hola]" / vacío tras sanitizar
if (!skipReply && !esOffTopic) {
  const soloBasura = !String(respuestaBot || '').trim() ||
    /^(hola|buenas?)[\s!.?\]]*$/i.test(String(respuestaBot || '').trim());
  if (soloBasura) {
    if (propiedadesMostrar.length) {
      respuestaBot = 'Mira estas';
    } else if (isRateLimit && !retryGroq) {
      respuestaBot = notifyOwnerGroq ? FALLBACK_GROQ : FALLBACK_RATE_LIMIT;
    } else if (groqFailed && !retryGroq) {
      respuestaBot = FALLBACK_GROQ;
    } else if (esSaludoSimple(textoUsuario) || esSaludoTurno) {
      respuestaBot =
        typeof saludoHumanoCorto === 'function'
          ? saludoHumanoCorto(turno)
          : SALUDOS_HUMANOS[0];
    } else {
      respuestaBot = FALLBACK_GROQ;
    }
  }
}

// Regla de oro: nunca narrar entrega de FICHAS si no hay fichas en este turno.
// No aplica a derivacion C ("Te paso con el vendedor") ni handoff de visita.
const PROMESA_ENTREGA_RE =
  /\b(te muestro|ah[ií] van|aca te (dejo|muestro)|ac[aá] te (dejo|muestro)|mir[aá] estas|te paso (estas|opciones|fichas|las|los|unos)|te mando|te env[ií]o|te dejo estas|ahora te (paso|mando|muestro))\b/i;
const skipPromesaEntrega =
  (derivacion && derivacion.categoria === 'C') ||
  forzarHandoffVisita ||
  Boolean(scoreTemp && scoreTemp.bot_paused && derivacion && derivacion.alertar);
if (
  !skipPromesaEntrega &&
  !propiedadesMostrar.length &&
  PROMESA_ENTREGA_RE.test(String(respuestaBot || ''))
) {
  if (isRateLimit && retryGroq) {
    respuestaBot = '';
  } else if (isRateLimit && notifyOwnerGroq) {
    respuestaBot = FALLBACK_GROQ;
  } else if (isRateLimit) {
    respuestaBot = FALLBACK_RATE_LIMIT;
  } else if (sugerenciasIds.length && (forzarStockClasificador || debeMostrar || pideStockTexto)) {
    propiedadesMostrar = sugerenciasIds.slice(0, 3);
    respuestaBot =
      typeof armarIntroPropiedades === 'function'
        ? armarIntroPropiedades(presupuestoDetectado, idxVariante, esCurioso)
        : 'Mira estas';
    mensajeCierre = typeof MENSAJE_CIERRE_PROPS !== 'undefined' ? MENSAJE_CIERRE_PROPS : mensajeCierre;
  } else {
    respuestaBot = String(respuestaBot || '')
      .replace(PROMESA_ENTREGA_RE, '')
      .replace(/\s{2,}/g, ' ')
      .trim();
    if (!respuestaBot) {
      respuestaBot =
        typeof preguntaAlgoPensado === 'function'
          ? preguntaAlgoPensado(turno)
          : 'Tenes algo pensado de zona o presupuesto, o preferis que te muestre opciones?';
    }
  }
}
if (propiedadesMostrar.length && !String(respuestaBot || '').trim()) {
  respuestaBot = 'Mira estas';
}

mensajeCierre = humanizarVoz(sanitizarPuntuacion(mensajeCierre));
if (mensajesExtra.length) {
  mensajesExtra = mensajesExtra
    .map((x) => humanizarVoz(sanitizarPuntuacion(x)))
    .filter(Boolean);
}

const aprendizajeOpts = {
  contexto_cliente: textoUsuario,
  respuesta_matias: respuestaBot,
  canal: 'telegram',
  zona: leadData.zona || visitaData.zona || zonaDetectada,
  operacion: leadData.operacion || '',
  presupuesto: presupuestoOut,
  temperatura,
  intencion: leadData.operacion || intencionClasificador || '',
  intencion_clasificador: intencionClasificador,
  lead_completo: leadCompleto,
  skip_reply: skipReply,
  es_off_topic: esOffTopic,
  fecha: ahora,
};
let regAprendizaje = {};
try {
  regAprendizaje =
    typeof prepararRegistroAprendizaje === 'function'
      ? prepararRegistroAprendizaje(aprendizajeOpts) || {}
      : {};
} catch (eAprend) {
  regAprendizaje = {};
}

if (promptData.sheets_error) {
  respuestaBot = 'Dame un rato que chequeo disponibilidad y te confirmo';
  propiedadesMostrar = [];
  mensajesExtra = [];
  mensajeCierre = '';
} else if (typeof precioPedidoDesdeStock === 'function') {
  let stockRowsPrecio = [];
  try {
    stockRowsPrecio = JSON.parse(promptData.stock_rows_json || '[]');
  } catch (ePrecio) {
    stockRowsPrecio = [];
  }
  const pedidoPrecio = precioPedidoDesdeStock(textoUsuario, stockRowsPrecio);
  if (pedidoPrecio && pedidoPrecio.texto) {
    respuestaBot = pedidoPrecio.texto;
    if (pedidoPrecio.id && propiedadesMostrar.indexOf(pedidoPrecio.id) < 0) {
      propiedadesMostrar.unshift(pedidoPrecio.id);
    }
  }
}

return [
  {
    json: {
      chat_id: chatId,
      nombre_usuario: nombreUsuario,
      lead_completo: leadCompleto,
      respuesta_bot: respuestaBot || (propiedadesMostrar.length ? 'Mira estas' : 'Buenas, en que te ayudo?'),
      historial_json: JSON.stringify(historialJson),
      turno: turno,
      row_exists: rowExists,
      fecha: ahora,
      nombre: leadData.nombre || nombreUsuario,
      zona: leadData.zona || visitaData.zona || '',
      presupuesto: presupuestoOut,
      tipo_operacion: leadData.operacion || '',
      temperatura: temperatura,
      resumen: leadData.resumen || '',
      texto_usuario: textoUsuario,
      propiedad_seguimiento: propiedadSeguimiento,
      propiedades_mostrar: JSON.stringify(propiedadesMostrar),
      solicitud_visita: solicitudVisita,
      visita_propiedad_id: String(visitaData.propiedad_id || ''),
      visita_nota: String(visitaData.nota || ''),
      mensaje_cierre: mensajeCierre,
      mensajes_extra: JSON.stringify(mensajesExtra),
      repeticion_detectada: repeticionDetectada,
      skip_reply: skipReply,
      bot_paused: scoreTemp.bot_paused ? 'si' : 'no',
      handoff: scoreTemp.handoff ? 'si' : 'no',
      estado_seguimiento: scoreTemp.estado_seguimiento || 'ninguno',
      senales_json: JSON.stringify(scoreTemp.senales || {}),
      senales_fuertes: (scoreTemp.senales_fuertes || []).join(','),
      notif_resumen: scoreTemp.notif_resumen || avisoVendedorTexto || '',
      temperatura_motivo: scoreTemp.motivo || '',
      es_off_topic: esOffTopic,
      off_topic_count: offTopicCount,
      rate_limit: isRateLimit,
      groq_failed: groqFailed,
      reenvio_rate_limit: reenvioRateLimit,
      reenvio_tipo: reenvioTipo,
      reenvio_ids: JSON.stringify(reenvioIds),
      reenvio_link: reenvioLink,
      retry_groq: retryGroq,
      wait_retry_sec: waitRetrySec,
      notify_owner_groq: notifyOwnerGroq,
      needs_advisor_action: Boolean(
        notifyOwnerGroq ||
          scoreTemp.bot_paused ||
          forzarHandoffVisita ||
          derivacion.alertar,
      ),
      aviso_vendedor: Boolean(derivacion.alertar),
      aviso_vendedor_texto: avisoVendedorTexto || '',
      derivacion_categoria: derivacion.categoria || 'A',
      derivacion_motivo: derivacion.motivo || 'auto',
      sheets_error: Boolean(promptData.sheets_error),
      cita_link: citaLinkParse,
      ...regAprendizaje,
    },
  },
];

/**
 * Prepara una fila para la hoja `Conversaciones_Revision` (revisión humana).
 *
 * Entradas esperadas desde el workflow:
 * - `repeticion_detectada` (boolean)
 * - `lead_completo` (WA: 'si'/'no' | TG: boolean)
 * - turnos: WA usa `consultas_count` como proxy, TG usa `turno`
 * - `historial_json` (string JSON)
 * - `mensajes_extra` (string JSON de mensajes adicionales, si existe)
 * - último mensaje + respuesta:
 *   - WA: `mensaje` + `respuesta_wa`
 *   - TG: `texto_usuario` + `respuesta_bot`
 */

const CANAL = 'telegram';
const UMBRAL_TURNOS_SIN_CLASIFICAR = 6;

function leadCompletoToBool(v) {
  if (typeof v === 'boolean') return v;
  const s = String(v || '').trim().toLowerCase();
  if (!s) return false;
  return s === 'si' || s === 'true' || s === 'calificado' || s === '1';
}

const repeticionDetectada = Boolean($json.repeticion_detectada);
const rateLimit = Boolean($json.rate_limit);
const leadCompleto = leadCompletoToBool($json.lead_completo);

// Proxy determinístico de "turnos" sin tocar el clasificador/IA
const turnos = Number($json.turno || $json.consultas_count || 0) || 0;
const sinClasificar = !leadCompleto && turnos >= UMBRAL_TURNOS_SIN_CLASIFICAR;

let motivo = '';
if ($json.sheets_error) motivo = 'sheets_error';
else if (rateLimit) motivo = 'rate_limit';
else if (repeticionDetectada) motivo = 'REPETICION';
else if (sinClasificar) motivo = 'SIN_CLASIFICAR';

const registrar_revision = Boolean(motivo);
const fecha_hora = new Date().toISOString();

const chat_id = String($json.chat_id || '').trim();
const lead_name = String($json.lead_name || $json.nombre_usuario || '').trim();
const ultimo_mensaje_cliente = String($json.texto_usuario || $json.mensaje || '').trim();
const respuesta_bot = String($json.respuesta_bot || $json.respuesta_wa || '').trim();

return [
  {
    json: {
      registrar_revision,
      motivo,
      fecha_hora,
      canal: CANAL,
      chat_id,
      lead_name,
      ultimo_mensaje_cliente,
      respuesta_bot,
      historial_json: String($json.historial_json || '[]'),
      mensajes_extra: String($json.mensajes_extra || '[]'),
    },
  },
];

/**
 * Bot Telegram — Transcribe voice/audio con Groq Whisper.
 * Tokens se sustituyen en --deploy (__SET_*__).
 */
const TG_TOKEN = '__SET_TELEGRAM_BOT_TOKEN__';
const GROQ_KEY = '__SET_GROQ_API_KEY__';

const prev = $input.first().json;
const trigger = $('Telegram Trigger').first().json;
const msg = (trigger && trigger.message) || trigger || {};
const voice = msg.voice || msg.audio || null;
const fileId = String(
  prev.voice_file_id || (voice && voice.file_id) || '',
).trim();
const textoYa = String(prev.texto_usuario || msg.text || msg.caption || '').trim();

if (!fileId || textoYa) {
  return [
    {
      json: {
        ...prev,
        texto_usuario: textoYa || String(prev.texto_usuario || ''),
        es_audio_sin_transcripcion: false,
      },
    },
  ];
}

function buildMultipart(buffer, filename, mime) {
  const boundary = '----NodoAudioTg' + Date.now();
  const headFile =
    '--' +
    boundary +
    '\r\nContent-Disposition: form-data; name="file"; filename="' +
    filename +
    '"\r\nContent-Type: ' +
    mime +
    '\r\n\r\n';
  const fields =
    '--' +
    boundary +
    '\r\nContent-Disposition: form-data; name="model"\r\n\r\nwhisper-large-v3-turbo\r\n' +
    '--' +
    boundary +
    '\r\nContent-Disposition: form-data; name="language"\r\n\r\nes\r\n';
  const end = '\r\n--' + boundary + '--\r\n';
  return {
    boundary,
    body: Buffer.concat([
      Buffer.from(fields, 'utf8'),
      Buffer.from(headFile, 'utf8'),
      Buffer.from(buffer),
      Buffer.from(end, 'utf8'),
    ]),
  };
}

async function transcribir() {
  if (!TG_TOKEN || TG_TOKEN.includes('SET_TELEGRAM') || !GROQ_KEY || GROQ_KEY.includes('SET_GROQ')) {
    return {
      ...prev,
      texto_usuario: '',
      es_audio_sin_transcripcion: true,
      audio_error: 'faltan_credenciales',
    };
  }

  const info = await this.helpers.httpRequest({
    method: 'GET',
    url:
      'https://api.telegram.org/bot' +
      TG_TOKEN +
      '/getFile?file_id=' +
      encodeURIComponent(fileId),
    json: true,
  });
  const filePath = String((info && info.result && info.result.file_path) || '').trim();
  if (!filePath) {
    return { ...prev, texto_usuario: '', es_audio_sin_transcripcion: true, audio_error: 'sin_file' };
  }

  const bin = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.telegram.org/file/bot' + TG_TOKEN + '/' + filePath,
    encoding: 'arraybuffer',
  });
  const buffer = Buffer.isBuffer(bin) ? bin : Buffer.from(bin);
  if (!buffer.length) {
    return { ...prev, texto_usuario: '', es_audio_sin_transcripcion: true, audio_error: 'audio_vacio' };
  }

  const mime = String((voice && voice.mime_type) || 'audio/ogg');
  const { body, boundary } = buildMultipart(buffer, 'voz.ogg', mime);
  const whisper = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.groq.com/openai/v1/audio/transcriptions',
    headers: {
      Authorization: 'Bearer ' + GROQ_KEY,
      'Content-Type': 'multipart/form-data; boundary=' + boundary,
    },
    body,
    json: true,
  });
  const texto = String((whisper && whisper.text) || '').trim();
  if (!texto) {
    return { ...prev, texto_usuario: '', es_audio_sin_transcripcion: true, audio_error: 'sin_texto' };
  }
  return {
    ...prev,
    texto_usuario: texto,
    es_audio: true,
    es_audio_transcrito: true,
    es_audio_sin_transcripcion: false,
    audio_transcripto: texto,
  };
}

try {
  const out = await transcribir.call(this);
  return [{ json: out }];
} catch (e) {
  return [
    {
      json: {
        ...prev,
        texto_usuario: '',
        es_audio_sin_transcripcion: true,
        audio_error: String((e && e.message) || e || 'transcribe_fail').slice(0, 180),
      },
    },
  ];
}

/**
