  prompt = $('Construir Prompt').first().json || {};
} catch (e) {
  prompt = {};
}
const prev = $input.first().json || {};
return [
  {
    json: {
      ...prompt,
      es_retry_groq: true,
      wait_retry_sec: Number(prev.wait_retry_sec) || 0,
      chat_id: String(prompt.chat_id || prev.chat_id || ''),
      messages: prompt.messages || prev.messages || [],
    },
  },
];

const j = $input.first().json || {};
let parsed = {};
try { parsed = $('Parsear Respuesta').first().json || {}; } catch (e) { parsed = j; }
if (parsed.retry_groq || j.retry_groq) {
  let prompt = {};
  try { prompt = $('Construir Prompt').first().json || {}; } catch (e2) { prompt = {}; }
  return [{ json: { ...prompt, es_retry_groq: true, retry_groq: true, wait_retry_sec: Number(parsed.wait_retry_sec || j.wait_retry_sec) || 45, _route: 'retry_groq', messages: prompt.messages || [] } }];
}
return [{ json: { ...parsed, ...j, _route: 'reenvio' } }];

/**
 * Cola justa de TPM Groq (antes de HTTP Groq).
 * 5 chats a la vez → cada uno toma un slot (~1 llamada / ventana),
 * esperando en silencio hasta 5 min. Configurable vía staticData.
 *
 * Free ~8k TPM → ~1 llamada grande/min. Developer: subir tpmBudget.
 */
const j = $input.first().json || {};
const chatId = String(j.chat_id || '').trim();

const DEFAULT_TPM = 7500; // headroom bajo 8k free
const DEFAULT_EST = 5200; // pedidos reales ~5k
const MAX_WAIT_MS = 5 * 60 * 1000;
const MIN_SLOT_MS = 20 * 1000;

const sd = $getWorkflowStaticData('global');
if (!sd.groqTokenCtrl) {
  sd.groqTokenCtrl = {
    nextSlotAt: 0,
    tpmBudget: DEFAULT_TPM,
    estTokens: DEFAULT_EST,
    maxWaitMs: MAX_WAIT_MS,
    byChat: {},
  };
}
const ctrl = sd.groqTokenCtrl;
if (!ctrl.byChat) ctrl.byChat = {};

const tpm = Math.max(2000, Number(ctrl.tpmBudget) || DEFAULT_TPM);
const est = Math.max(1500, Number(ctrl.estTokens) || DEFAULT_EST);
const maxWait = Math.max(60000, Number(ctrl.maxWaitMs) || MAX_WAIT_MS);
const slotMs = Math.max(MIN_SLOT_MS, Math.ceil((60000 * est) / tpm));

const now = Date.now();
// Si un 429 reciente empujó nextSlotAt, respetarlo
let slotAt = Math.max(Number(ctrl.nextSlotAt) || 0, now);
let waitMs = Math.max(0, slotAt - now);

if (waitMs > maxWait) {
  // Cola saturada: avisar dueño (flag) pero igual capar a maxWait
  waitMs = maxWait;
  slotAt = now + maxWait;
  ctrl.cola_saturada = true;
} else {
  ctrl.cola_saturada = false;
}

ctrl.nextSlotAt = slotAt + slotMs;
ctrl.byChat[chatId] = {
  reservedAt: now,
  slotAt,
  waitMs,
  slotMs,
};

return [
  {
    json: {
      ...j,
      wait_cola_sec: Math.ceil(waitMs / 1000),
      wait_cola_ms: waitMs,
      groq_slot_ms: slotMs,
      groq_tpm_budget: tpm,
      groq_est_tokens: est,
      groq_cola_saturada: Boolean(ctrl.cola_saturada),
    },
  },
];

const item = $input.first().json || {};
const updateId = Number(item.update_id || 0);
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.seenUpdateIds)) sd.seenUpdateIds = [];
if (updateId && sd.seenUpdateIds.indexOf(updateId) >= 0) return [];
if (updateId) {
  sd.seenUpdateIds.push(updateId);
  if (sd.seenUpdateIds.length > 200) sd.seenUpdateIds = sd.seenUpdateIds.slice(-200);
}
return [{ json: item }];
